    m=json.load(open(p+'/metadata.json'));ci={c:i for i,c in enumerate(m['columns'])}
    cmt=[c for c in m.get('comments',[]) if 'source=' in c]
    fn=p+'/data.tsv.gz' if os.path.exists(p+'/data.tsv.gz') else p+'/data.tsv'
    try:
        d=np.loadtxt(fn)
        if d.ndim==1: d=d.reshape(1,-1)
        I=np.median(d[:,ci['sr0_X']]/m['measurement_config']['sr0_gain'])
        import re
        s=re.search('source=(\\w+) drain=(\\w+)',cmt[0]); src,dst=s.group(1),s.group(2)
